-- Disposable fixtures only. Run as the project database administrator. Always rolls back.
begin;
create function pg_temp.assert_true(ok boolean,msg text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'TEST FAILED: %',msg;end if;end $$;
create temp table fixture(k text primary key,id uuid default gen_random_uuid());
insert into fixture(k) values('owner'),('manager'),('viewer'),('outsider'),('network'),('other_network'),('unit'),('second_unit'),('other_unit'),('sector'),('second_sector'),('role'),('person'),('assignment'),('second_assignment');
grant select on fixture to authenticated;
create function pg_temp.f(key text) returns uuid language sql as $$ select id from fixture where k=key $$;
insert into auth.users(id,email,email_confirmed_at,aud,role) select id,k||'-'||id::text||'@example.invalid',now(),'authenticated','authenticated' from fixture where k in('owner','manager','viewer','outsider');
insert into public.networks(id,name) values(pg_temp.f('network'),'Verification network'),(pg_temp.f('other_network'),'Unrelated verification network');
insert into public.units(id,network_id,name,code,settings) select f.id,case when f.k='other_unit' then pg_temp.f('other_network') else pg_temp.f('network') end,f.k,f.k,jsonb_set((select settings from public.units limit 1),'{policy}','{"weeklyHours":40,"dailyHours":8,"restHours":11,"maxWorkDays":5,"maxConsecutive":5}') from fixture f where k in('unit','second_unit','other_unit');
insert into public.memberships(user_id,network_id,unit_id,role) values(pg_temp.f('owner'),pg_temp.f('network'),null,'owner'),(pg_temp.f('manager'),pg_temp.f('network'),pg_temp.f('unit'),'manager'),(pg_temp.f('viewer'),pg_temp.f('network'),pg_temp.f('unit'),'viewer');
insert into public.sectors(id,unit_id,name) values(pg_temp.f('sector'),pg_temp.f('unit'),'Test sector'),(pg_temp.f('second_sector'),pg_temp.f('second_unit'),'Test sector');
insert into public.job_roles(id,network_id,name) values(pg_temp.f('role'),pg_temp.f('network'),'Test role');
insert into public.people(id,network_id,name,weekly_hours,contract_confirmed) values(pg_temp.f('person'),pg_temp.f('network'),'Test person',40,true);
insert into public.unit_assignments(id,unit_id,network_id,person_id,sector_id,role_id,starts_on) values(pg_temp.f('assignment'),pg_temp.f('unit'),pg_temp.f('network'),pg_temp.f('person'),pg_temp.f('sector'),pg_temp.f('role'),'2026-10-19'),(pg_temp.f('second_assignment'),pg_temp.f('second_unit'),pg_temp.f('network'),pg_temp.f('person'),pg_temp.f('second_sector'),pg_temp.f('role'),'2026-10-19');
select set_config('request.jwt.claim.sub',pg_temp.f('owner')::text,true);
set local role authenticated;
select pg_temp.assert_true((select count(*)=1 from public.networks),'owner network isolation');
select pg_temp.assert_true((select count(*)=2 from public.units),'owner units isolation');
do $$ declare v integer;a uuid;r public.schedules;rows jsonb;issues jsonb;before_name text;rule_id uuid;begin
 select revision into v from public.units where id=pg_temp.f('unit');
 perform public.mutate_configuration(pg_temp.f('unit'),v,'sectors',jsonb_build_object('name','New test sector'),false);
 begin perform public.mutate_configuration(pg_temp.f('unit'),v,'sectors',jsonb_build_object('name','Stale write'),false);raise exception 'TEST FAILED stale revision accepted';exception when serialization_failure then null;end;
 select revision into v from public.units where id=pg_temp.f('unit');
 begin perform public.save_employee(pg_temp.f('unit'),v,pg_temp.f('assignment'),jsonb_build_object('name','Should roll back','weekly_hours',40,'contract_confirmed',true),jsonb_build_object('role_id',gen_random_uuid()));raise exception 'TEST FAILED invalid role accepted';exception when foreign_key_violation then null;end;
 perform pg_temp.assert_true((select name='Test person' from public.people where id=pg_temp.f('person')),'employee edits atomic');
 select revision into v from public.units where id=pg_temp.f('unit');
 a=public.save_employee(pg_temp.f('unit'),v,null,jsonb_build_object('name','New test person','weekly_hours',40,'contract_confirmed',true),jsonb_build_object('sector_id',pg_temp.f('sector'),'role_id',pg_temp.f('role'),'weekdays',jsonb_build_array(0,1,2,3,4,5,6),'starts_on','2026-10-19','active',true));
 perform pg_temp.assert_true(a is not null,'new employee inserted');
 select jsonb_agg(jsonb_build_object('assignment_id',x.id,'person_id',x.person_id,'work_date',d::date,'kind',case when x.id=pg_temp.f('assignment') and d::date='2026-10-19' then 'work' else 'off' end,'sector_id',x.sector_id,'role_id',x.role_id,'start_time','07:00','end_time','16:00','break_start','11:00','break_end','12:00')) into rows from public.unit_assignments x cross join generate_series('2026-10-19'::timestamp,'2026-10-25'::timestamp,'1 day') d where x.unit_id=pg_temp.f('unit');
 select revision into v from public.units where id=pg_temp.f('unit');
 r=public.save_schedule(pg_temp.f('unit'),'2026-10-19',0,v,rows,'Verification');
 perform pg_temp.assert_true(not exists(select 1 from jsonb_array_elements(public.schedule_issues(r.id)) i where i->>'level'='block'),'valid complete plan');
 begin perform public.save_schedule(pg_temp.f('unit'),'2026-10-19',0,v,rows,'stale');raise exception 'TEST FAILED schedule concurrency';exception when serialization_failure then null;end;
 begin perform public.save_schedule(pg_temp.f('unit'),'2026-10-19',null,v,rows,'null revision');raise exception 'TEST FAILED null revision';exception when serialization_failure then null;end;
 begin perform public.save_schedule(pg_temp.f('unit'),'2026-10-19',r.revision,v,jsonb_set(jsonb_set(rows,'{0,kind}','"work"'),'{0,end_time}','null'),'invalid');raise exception 'TEST FAILED null shift times';exception when check_violation then null;end;
 select (public.mutate_configuration(pg_temp.f('unit'),v,'coverage_requirements',jsonb_build_object('sector_id',pg_temp.f('sector'),'role_id',pg_temp.f('role'),'weekdays',jsonb_build_array(0),'minimum',1,'mode','simultaneous','start_time','10:45','end_time','11:15','effective_from','2026-10-19','confirmed',true,'blocking',true),false)->>'id')::uuid into rule_id;
 perform pg_temp.assert_true(exists(select 1 from jsonb_array_elements(public.schedule_issues(r.id)) i where i->>'code'='coverage' and i->>'level'='block'),'break reduces simultaneous coverage');
 select revision into v from public.units where id=pg_temp.f('unit');
 begin perform public.publish_schedule(r.id,r.revision,v,true);raise exception 'TEST FAILED coverage publication accepted';exception when raise_exception then if SQLERRM like 'TEST FAILED%' then raise;end if;end;
 -- Closure removes only the closed part of a timed requirement.
 perform public.mutate_configuration(pg_temp.f('unit'),v,'units',jsonb_build_object('id',pg_temp.f('unit'),'settings',jsonb_set((select settings from public.units where id=pg_temp.f('unit')),'{opening,0,closure}','{"start":"11:00","end":"11:15"}')),false);
 perform pg_temp.assert_true(not exists(select 1 from jsonb_array_elements(public.schedule_issues(r.id)) i where i->>'code'='coverage'),'closure excludes only the covered closed segment');
 select revision into v from public.units where id=pg_temp.f('unit');
 perform public.mutate_configuration(pg_temp.f('unit'),v,'coverage_requirements',jsonb_build_object('id',rule_id,'end_time','11:30'),false);
 perform pg_temp.assert_true(exists(select 1 from jsonb_array_elements(public.schedule_issues(r.id)) i where i->>'code'='coverage'),'reopening restores coverage demand');
 select revision into v from public.units where id=pg_temp.f('unit');
 perform public.mutate_configuration(pg_temp.f('unit'),v,'coverage_requirements',jsonb_build_object('id',rule_id,'start_time','11:00','end_time','11:15'),false);
 perform pg_temp.assert_true(not exists(select 1 from jsonb_array_elements(public.schedule_issues(r.id)) i where i->>'code'='coverage'),'fully closed timed requirement suspended');
 select revision into v from public.units where id=pg_temp.f('unit');
 begin perform public.mutate_configuration(pg_temp.f('unit'),v,'units',jsonb_build_object('id',pg_temp.f('unit'),'settings',jsonb_set((select settings from public.units where id=pg_temp.f('unit')),'{opening,0,closure}','{"start":"14:00","end":"12:00"}')),false);raise exception 'TEST FAILED invalid closure saved';exception when raise_exception then if SQLERRM like 'TEST FAILED%' then raise;end if;end;
 perform public.mutate_configuration(pg_temp.f('unit'),v,'units',jsonb_build_object('id',pg_temp.f('unit'),'settings',jsonb_set((select settings from public.units where id=pg_temp.f('unit')),'{opening,0,closure}','null')),false);
 perform pg_temp.assert_true(exists(select 1 from jsonb_array_elements(public.schedule_issues(r.id)) i where i->>'code'='coverage'),'continuous unit keeps timed demand');
 select revision into v from public.units where id=pg_temp.f('unit');
 perform public.mutate_configuration(pg_temp.f('unit'),v,'coverage_requirements',jsonb_build_object('id',rule_id,'start_time','10:00','end_time','10:15','mode','opening'),false);
 perform pg_temp.assert_true(exists(select 1 from jsonb_array_elements(public.schedule_issues(r.id)) i where i->>'code'='coverage'),'opening requires explicit qualification');
 select revision into v from public.units where id=pg_temp.f('unit');
 perform public.mutate_configuration(pg_temp.f('unit'),v,'unit_assignments',jsonb_build_object('id',pg_temp.f('assignment'),'can_open',true),false);
 perform pg_temp.assert_true(not exists(select 1 from jsonb_array_elements(public.schedule_issues(r.id)) i where i->>'code'='coverage'),'short exact coverage with qualified opener');
 select revision into v from public.units where id=pg_temp.f('unit');
 perform public.publish_schedule(r.id,r.revision,v,true);
 perform pg_temp.assert_true((select count(*)=1 from public.published_schedules where schedule_id=r.id),'publication stored');
 perform pg_temp.assert_true((select snapshot ? 'assignments' from public.published_schedules where schedule_id=r.id),'publication preserves opening qualifications');
 begin update public.published_schedules set snapshot='{}' where schedule_id=r.id;raise exception 'TEST FAILED immutable publication';exception when insufficient_privilege then null;end;
 select * into r from public.schedules where id=r.id;
 r=public.revise_schedule(r.id,r.revision,'Verification revision');
 perform pg_temp.assert_true((select count(*)=1 from public.published_schedules where schedule_id=r.id),'revision preserves old publication');
 -- A published shift remains a commitment while a changed draft exists.
 rows=jsonb_set(rows,'{0,kind}','"off"');
 r=public.save_schedule(pg_temp.f('unit'),'2026-10-19',r.revision,v,rows,'Verification');
end $$;
reset role;
-- Force two-unit total above the contract, without touching any operational record.
update public.people set weekly_hours=8 where id=pg_temp.f('person');
insert into public.schedules(unit_id,week_start) values(pg_temp.f('second_unit'),'2026-10-19');
insert into public.schedule_entries(schedule_id,unit_id,network_id,assignment_id,person_id,work_date,kind,sector_id,role_id,start_time,end_time,break_start,break_end) select s.id,s.unit_id,pg_temp.f('network'),pg_temp.f('second_assignment'),pg_temp.f('person'),d::date,case when d::date='2026-10-21' then 'work' else 'off' end,pg_temp.f('second_sector'),pg_temp.f('role'),case when d::date='2026-10-21' then '07:00'::time end,case when d::date='2026-10-21' then '16:00'::time end,case when d::date='2026-10-21' then '11:00'::time end,case when d::date='2026-10-21' then '12:00'::time end from public.schedules s cross join generate_series('2026-10-19'::timestamp,'2026-10-25'::timestamp,'1 day') d where s.unit_id=pg_temp.f('second_unit');
set local role authenticated;
select pg_temp.assert_true(exists(select 1 from jsonb_array_elements(public.schedule_issues((select id from public.schedules where unit_id=pg_temp.f('second_unit')))) i where i->>'code'='weekly'),'global weekly hours including revised publication');
reset role;
select set_config('request.jwt.claim.sub',pg_temp.f('manager')::text,true);
set local role authenticated;
select pg_temp.assert_true((select count(*)=1 from public.units),'manager sees own unit only');
select pg_temp.assert_true((select count(*)=1 from public.networks),'manager sees network label');
do $$ begin
 begin perform public.create_unit(pg_temp.f('network'),'Forbidden','forbidden');raise exception 'TEST FAILED manager creates unit';exception when raise_exception then if SQLERRM like 'TEST FAILED%' then raise;end if;end;
 begin perform public.mutate_configuration(pg_temp.f('second_unit'),1,'sectors',jsonb_build_object('name','Forbidden'),false);raise exception 'TEST FAILED cross unit write';exception when raise_exception then if SQLERRM like 'TEST FAILED%' then raise;end if;end;
 begin insert into public.memberships(user_id,network_id,unit_id,role) values(pg_temp.f('manager'),pg_temp.f('network'),null,'owner');raise exception 'TEST FAILED self elevation';exception when insufficient_privilege then null;end;
end $$;
reset role;
select set_config('request.jwt.claim.sub',pg_temp.f('viewer')::text,true);
set local role authenticated;
do $$ declare v int;begin
 select revision into v from public.units where id=pg_temp.f('unit');
 begin perform public.mutate_configuration(pg_temp.f('unit'),v,'sectors',jsonb_build_object('name','Forbidden'),false);raise exception 'TEST FAILED viewer write';exception when raise_exception then if SQLERRM like 'TEST FAILED%' then raise;end if;end;
end $$;
reset role;
select set_config('request.jwt.claim.sub',pg_temp.f('outsider')::text,true);
set local role authenticated;
select pg_temp.assert_true((select count(*)=0 from public.units),'uninvited account cannot read units');
select pg_temp.assert_true((select count(*)=0 from public.people),'uninvited account cannot read employees');
reset role;
set local role anon;
do $$ begin
 begin perform count(*) from public.people;raise exception 'TEST FAILED anonymous employee access';exception when insufficient_privilege then null;end;
 begin perform public.accept_access();raise exception 'TEST FAILED anonymous RPC';exception when insufficient_privilege then null;end;
end $$;
reset role;
rollback;
select 'passed: isolation, atomic edits, optimistic concurrency, publication, shared hours, manager/viewer/anonymous permissions' as verification;
